// ═══ CREATING A DAEMON THREAD ═══
Thread daemon = new Thread(() -> {
    while (true) {
        refreshCache();       // background cache refresh
        Thread.sleep(30000);  // every 30 seconds
    }
});
daemon.setDaemon(true);   // MUST be before start()!
daemon.start();
// When all non-daemon threads finish → JVM exits → daemon killed abruptly!
// finally blocks in daemon thread may NOT execute!

// ═══ USER (NON-DAEMON) THREAD ═══
Thread user = new Thread(() -> {
    processAllTrades();
    // JVM waits for this thread to finish!
});
user.setDaemon(false);  // default — non-daemon
user.start();

// ═══ RULES ═══
// 1. setDaemon() MUST be called BEFORE start()
//    After start() → IllegalThreadStateException!
// 2. Child threads INHERIT parent's daemon status
//    Daemon thread creates a thread → child is daemon too
// 3. Main thread is NON-daemon
// 4. JVM exits when: ALL non-daemon threads terminate
//    Daemon threads are killed without warning!

// ═══ setDaemon AFTER start → exception! ═══
Thread t = new Thread(() -> {});
t.start();
// t.setDaemon(true);  → IllegalThreadStateException!

// ═══ DAEMON IN THREAD POOL ═══
ExecutorService pool = Executors.newFixedThreadPool(4, r -> {
    Thread t = new Thread(r);
    t.setDaemon(true);  // all pool threads are daemon!
    t.setName("daemon-worker-" + t.getId());
    return t;
});
// Pool threads won't prevent JVM exit!
// Good for: optional background processing
// Bad for: critical work that MUST complete!

// ═══ IMPORTANT: finally NOT guaranteed in daemon! ═══
Thread daemon2 = new Thread(() -> {
    try {
        Thread.sleep(Long.MAX_VALUE);
    } finally {
        saveData();  // MAY NOT EXECUTE if JVM exits!
        // JVM kills daemon threads without running finally!
    }
});
daemon2.setDaemon(true);
daemon2.start();
// If all user threads end → JVM exits → finally SKIPPED!
