// ─── File: src/test/java/com/bank/daemon/DaemonThreadTest.java ───
package com.bank.daemon;

import org.junit.jupiter.api.Test;
import java.util.concurrent.*;
import java.util.concurrent.atomic.*;
import static org.assertj.core.api.Assertions.*;

class DaemonThreadTest {

    // ═══ Daemon thread: isDaemon() ═══
    @Test
    void daemonStatus() {
        Thread daemon = new Thread(() -> {});
        daemon.setDaemon(true);
        assertThat(daemon.isDaemon()).isTrue();

        Thread user = new Thread(() -> {});
        assertThat(user.isDaemon()).isFalse();  // default: non-daemon
    }

    // ═══ setDaemon after start → exception ═══
    @Test
    void setDaemon_afterStart_throwsException() {
        Thread t = new Thread(() -> {
            try { Thread.sleep(1000); } catch (InterruptedException e) { }
        });
        t.start();
        assertThatThrownBy(() -> t.setDaemon(true))
            .isInstanceOf(IllegalThreadStateException.class);
        t.interrupt();
    }

    // ═══ Child inherits daemon status ═══
    @Test
    void childInheritsDaemonStatus() throws InterruptedException {
        AtomicBoolean childIsDaemon = new AtomicBoolean(false);
        CountDownLatch done = new CountDownLatch(1);

        Thread parentDaemon = new Thread(() -> {
            Thread child = new Thread(() -> {
                childIsDaemon.set(Thread.currentThread().isDaemon());
                done.countDown();
            });
            child.start();
        });
        parentDaemon.setDaemon(true);
        parentDaemon.start();

        done.await(5, TimeUnit.SECONDS);
        assertThat(childIsDaemon.get()).isTrue();  // child inherited daemon!
    }

    // ═══ Daemon pool using ThreadFactory ═══
    @Test
    void daemonThreadPool() throws InterruptedException {
        ExecutorService pool = Executors.newFixedThreadPool(2, r -> {
            Thread t = new Thread(r);
            t.setDaemon(true);
            return t;
        });

        AtomicBoolean isDaemon = new AtomicBoolean(false);
        CountDownLatch done = new CountDownLatch(1);

        pool.submit(() -> {
            isDaemon.set(Thread.currentThread().isDaemon());
            done.countDown();
        });

        done.await(5, TimeUnit.SECONDS);
        assertThat(isDaemon.get()).isTrue();  // pool worker is daemon!
        pool.shutdown();
    }

    // ═══ Main thread is non-daemon ═══
    @Test
    void mainThread_isNonDaemon() {
        assertThat(Thread.currentThread().isDaemon()).isFalse();
    }
}
